//  the actual behaviour is marked TODO for you to fill in.
//
//  Kind=9   mex=AiSetup.mex   status=stub
//  Window: 520x380 (min 360x280) -- note the kernel currently builds
//  standalone windows at 480x360 (gui_legacy.cpp:8541); change that
//  default or pass a size before these numbers become authoritative.
//
//  CONTRACT (mforms.cpp slot_symbol):
//    App.Main::Init / Paint(id,w,h) / Click(id,x,y) / Key(id,ch) / Title(id)
//  Each window owns its own CLR slot; `id` is the opaque window handle
//  (NEX_APP_HANDLE_BASE + slot), NOT a shared static index.
//
//  MiniCLR limits: no System.Collections, no string '+', no static
//  initialisers, no float/generic/try-catch.  Use U.Cat for strings,
//  fixed-size arrays + linear search instead of Dictionary, and never
//  hold a newly allocated object across Paint frames.
// ---------------------------------------------------------------------

// Event sequence (from specs.json):
//   - Init 置 step=0
//   - Click next 校验当前步再前进
//   - 最后一步写配置并调 Host.Log
//   - Esc 直接取消不写盘
// Acceptance points:
//   - 四步可前进/后退
//   - 未选模型时 next 不可用
//   - 完成后状态可查询
// Right-click menu: 跳过向导 / 重新检测
// State fields to model: int step, int model, bool enabled, int detected
// =====================================================================

using NexOS.Forms;

namespace App
{
    public static class Main
    {
        // MiniCLR does NOT run .cctor: every static starts as null/0.
        // All state must be created explicitly inside Init().
        static AiSetupApp app;

        public static void Init()
        {
            if (app == null) app = new AiSetupApp();
        }

        public static int Paint(int id, int w, int h)
        {
            Init();
            app.OnPaint(id, w, h);
            return 0;
        }

        public static int Click(int id, int x, int y)
        {
            Init();
            return app.OnClick(id, x, y);
        }

        public static int Key(int id, int ch)
        {
            Init();
            return app.OnKey(id, ch);
        }

        public static string Title(int id)
        {
            Init();
            return app.GetTitle(id);
        }
    }

    public class AiSetupApp
    {
        // ---- window / document state (assigned in Init, never inline) ----
        string title;
        bool   dirty;
        int    focus;
        int    scroll;
        int    activeTab;

        // TODO(multi-window): one CLR slot per window already isolates
        // statics, but if this app ever shares a slot it MUST keep a
        // fixed-size Doc[] indexed by `id` (linear search, no Dictionary).

        public AiSetupApp()
        {
            title = "AI Setup";
            dirty = false;
            focus = 0;
            scroll = 0;
            activeTab = 0;
        }

        // ---- layout hit regions (from specs.json) ---------------------
        const int X_steps = 8, Y_steps = 8, W_steps = 504, H_steps = 44;
        const int X_body = 8, Y_body = 60, W_body = 504, H_body = 250;
        const int X_models = 20, Y_models = 84, W_models = 480, H_models = 180;
        const int X_prev = 322, Y_prev = 330, W_prev = 90, H_prev = 28;
        const int X_next = 422, Y_next = 330, W_next = 90, H_next = 28;

        static bool InRect(int x, int y, int rx, int ry, int rw, int rh)
        {
            return x >= rx && x < rx + rw && y >= ry && y < ry + rh;
        }

        public void OnPaint(int id, int w, int h)
        {
            // Only draw here.  Do NOT create objects that must survive
            // the frame: the bump heap is rewound after every Paint.
            // Client size is w x h; the constants above are prototype
            // coordinates and should be re-derived from w/h when the
            // kernel starts honouring per-app window sizes.
            W.Label(X_steps, Y_steps, "步骤");  // TODO: draw stepper
            W.Label(X_body, Y_body, "当前步骤内容");  // TODO: draw panel
            W.Label(X_models, Y_models, "可用模型");  // TODO: draw list
            W.Button(X_prev, Y_prev, W_prev, H_prev, "上一步");
            W.Button(X_next, Y_next, W_next, H_next, "下一步");
            // TODO: scrollbars, selection highlight, dirty marker,
            //       and any state-dependent greying-out of controls.
        }

        public int OnClick(int id, int x, int y)
        {
            // Return non-zero when the click is consumed by the app.
            // Coordinates are client-relative (mforms subtracts ox/oy).
            if (InRect(x, y, X_steps, Y_steps, W_steps, H_steps))
            {
                // TODO: stepper -> 步骤
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_body, Y_body, W_body, H_body))
            {
                // TODO: panel -> 当前步骤内容
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_models, Y_models, W_models, H_models))
            {
                // TODO: list -> 可用模型
                activeTab = 0;  // TODO: derive from x/y
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_prev, Y_prev, W_prev, H_prev))
            {
                // TODO: button -> 上一步
                dirty = true;
                return 1;
            }
            if (InRect(x, y, X_next, Y_next, W_next, H_next))
            {
                // TODO: button -> 下一步
                dirty = true;
                return 1;
            }
            return 0;
        }

        public int OnKey(int id, int ch)
        {
            // Return non-zero when consumed (Tab MUST be consumed so the
            // window manager does not move focus away).
            // TODO: obtain the authoritative key code table from
            // mforms_key -> gui_legacy.cpp before implementing these:
            //   Enter        -> 下一步
            //   Esc          -> 取消向导
            //   Up/Down      -> 选择模型
            if (ch == 9) return 1;   // Tab placeholder
            return 0;
        }

        public string GetTitle(int id)
        {
            // TODO: append the document name and a (saved) hint with
            // U.Cat -- never use string '+'.  clr_heap_mark/reset wraps
            // this call in mforms_title(), so the string is temporary.
            return title;
        }
    }
}
